export const LIFE_SCIENCES_BASICS_A_QUIZZES = [
  {
    id:`bb101`, cat:`Life Sciences`, title:`Skeletal System Basics`, diff:`Easy`,
    qs:[
      { q:`What is one of the main functions of the human skeletal system?`, ch:[`Providing structural support for the body`,`Producing digestive enzymes`,`Filtering blood in the kidneys`,`Regulating body temperature directly`], ans:0, exp:`The skeleton provides the rigid framework that supports the body, along with protecting organs, enabling movement with muscles, and storing minerals.` },
      { q:`Approximately how many bones are in the skeleton of a typical adult human?`, ch:[`106`,`206`,`306`,`406`], ans:1, exp:`The adult human skeleton has 206 bones. Babies are born with more bones (around 300), many of which fuse together during growth.` },
      { q:`Which tissue inside certain bones is responsible for producing most blood cells?`, ch:[`Cartilage`,`Periosteum`,`Red bone marrow`,`Yellow marrow fat`], ans:2, exp:`Red bone marrow, found in the spongy bone of certain bones like the pelvis and sternum, is where red blood cells, white blood cells, and platelets are produced.` },
      { q:`The knee joint, which allows movement mainly in one direction like a door, is classified as a:`, ch:[`Ball-and-socket joint`,`Pivot joint`,`Gliding joint`,`Hinge joint`], ans:3, exp:`A hinge joint, like the knee or elbow, permits movement primarily in one plane, similar to how a door hinge works.` },
      { q:`Which bony structure encloses and protects the brain?`, ch:[`The cranium (skull)`,`The sternum`,`The pelvis`,`The scapula`], ans:0, exp:`The cranium is the dome-shaped part of the skull that surrounds and protects the brain from injury.` },
      { q:`The rib cage mainly protects which two organs?`, ch:[`The kidneys and liver`,`The heart and lungs`,`The stomach and spleen`,`The brain and eyes`], ans:1, exp:`The rib cage forms a protective bony cage around the heart and lungs, shielding them from physical impact.` },
      { q:`Which of the following bones is classified as a long bone?`, ch:[`A carpal bone in the wrist`,`A vertebra`,`The femur (thigh bone)`,`A skull plate`], ans:2, exp:`The femur is the longest and strongest bone in the body and is a classic example of a long bone, with a shaft and two rounded ends.` },
      { q:`Cartilage is a flexible connective tissue found in body parts such as:`, ch:[`Bone marrow`,`Red blood cells`,`Tooth enamel`,`The outer ear and the tip of the nose`], ans:3, exp:`Cartilage is a tough but flexible tissue that gives shape and support to structures like the outer ear, nose tip, and the ends of bones at joints.` },
      { q:`Which structures connect bone to bone at a joint, providing stability?`, ch:[`Ligaments`,`Tendons`,`Nerves`,`Muscle fibers`], ans:0, exp:`Ligaments are tough bands of connective tissue that connect bones to other bones, stabilizing joints. Tendons, by contrast, connect muscle to bone.` },
      { q:`The vertebral column (spine) is primarily responsible for protecting the:`, ch:[`Heart`,`Spinal cord`,`Lungs`,`Kidneys`], ans:1, exp:`The vertebrae stack together to form a bony canal that surrounds and protects the delicate spinal cord running through the back.` },
      { q:`Compared to spongy (cancellous) bone, compact bone is:`, ch:[`Lighter and found only in the skull`,`Not present in the human body`,`Denser and forms the hard outer layer of bones`,`Softer and forms the innermost layer only`], ans:2, exp:`Compact bone is dense and forms the strong outer shell of bones, while spongy bone, found more internally, is lighter with a honeycomb-like structure.` },
    ]
  },
  {
    id:`bb102`, cat:`Life Sciences`, title:`Muscular System Basics`, diff:`Easy`,
    qs:[
      { q:`Which type of muscle is under voluntary control and attached to bones?`, ch:[`Cardiac muscle`,`Skeletal muscle`,`Smooth muscle`,`Involuntary muscle only`], ans:1, exp:`Skeletal muscle is attached to bones by tendons and can be consciously controlled, allowing voluntary movements like walking or lifting.` },
      { q:`Smooth muscle is typically found in which of the following?`, ch:[`The biceps`,`The heart wall only`,`The walls of organs such as the stomach and intestines`,`The face`], ans:2, exp:`Smooth muscle lines the walls of internal organs like the stomach, intestines, and blood vessels, and works involuntarily to move substances through the body.` },
      { q:`Cardiac muscle is found exclusively in the:`, ch:[`Arms and legs`,`Digestive tract`,`Diaphragm`,`Heart`], ans:3, exp:`Cardiac muscle is a specialized, striated muscle type found only in the heart, where it contracts rhythmically and involuntarily to pump blood.` },
      { q:`When a muscle contracts, it generally:`, ch:[`Shortens and pulls on the bone it is attached to`,`Lengthens permanently`,`Turns into bone tissue`,`Stops receiving nerve signals`], ans:0, exp:`Muscle contraction involves the muscle fibers shortening, which pulls on the tendon and moves the attached bone at a joint.` },
      { q:`Muscles that work in opposing pairs, such as the biceps and triceps, are called:`, ch:[`Synergist muscles`,`Antagonistic muscles`,`Fixator muscles`,`Cardiac muscles`], ans:1, exp:`Antagonistic muscle pairs work opposite each other: as one contracts (like the biceps to bend the elbow), the other relaxes (the triceps), and vice versa.` },
      { q:`Which protein filaments slide past each other to produce muscle contraction?`, ch:[`Collagen and elastin`,`Keratin and collagen`,`Actin and myosin`,`Hemoglobin and myoglobin`], ans:2, exp:`Muscle contraction occurs when thin actin filaments slide past thick myosin filaments within muscle fibers, shortening the muscle overall.` },
      { q:`Tendons attach muscle to:`, ch:[`Other muscles`,`Skin`,`Nerves`,`Bone`], ans:3, exp:`Tendons are tough, fibrous connective tissue that anchor muscles to bones, allowing muscle contraction to move the skeleton.` },
      { q:`Which of these is a characteristic of skeletal muscle tissue?`, ch:[`It appears striated (striped) under a microscope`,`It cannot be controlled voluntarily`,`It lacks a nerve supply`,`It contracts only in the heart`], ans:0, exp:`Skeletal muscle fibers have a striped, or striated, appearance under a microscope due to the organized arrangement of actin and myosin filaments.` },
      { q:`What is the immediate energy source that muscle cells use to power contraction?`, ch:[`Glucose alone, with no other molecule involved`,`ATP (adenosine triphosphate)`,`Oxygen alone`,`DNA`], ans:1, exp:`Muscle cells directly use ATP to power the sliding of actin and myosin filaments during contraction. Glucose and oxygen are used to help produce that ATP.` },
      { q:`During intense exercise, muscles that are low on oxygen may build up which byproduct, contributing to a burning sensation?`, ch:[`Carbon dioxide crystals`,`Glycogen`,`Lactic acid`,`Bile`], ans:2, exp:`When oxygen is limited during intense exercise, muscles rely more on anaerobic metabolism, producing lactic acid as a byproduct.` },
      { q:`Which muscle is the primary muscle used for breathing, contracting to pull air into the lungs?`, ch:[`The biceps`,`The masseter (jaw muscle)`,`The gluteus maximus`,`The diaphragm`], ans:3, exp:`The diaphragm is a dome-shaped muscle beneath the lungs that contracts and flattens to draw air into the lungs during inhalation.` },
    ]
  },
  {
    id:`bb103`, cat:`Life Sciences`, title:`The Urinary System Basics`, diff:`Easy`,
    qs:[
      { q:`What is the main function of the kidneys?`, ch:[`Producing red blood cells only`,`Digesting proteins`,`Filtering blood to remove waste and excess water`,`Pumping blood throughout the body`], ans:2, exp:`The kidneys filter blood continuously, removing metabolic waste products and excess water and forming urine as a result.` },
      { q:`Urine travels from each kidney to the bladder through a tube called the:`, ch:[`Urethra`,`Aorta`,`Trachea`,`Ureter`], ans:3, exp:`Each kidney connects to the bladder by a tube called the ureter, which carries urine downward using muscular contractions.` },
      { q:`Urine exits the body through a tube called the:`, ch:[`Urethra`,`Ureter`,`Esophagus`,`Bronchus`], ans:0, exp:`The urethra is the final tube that carries urine from the bladder out of the body during urination.` },
      { q:`The functional filtering unit of the kidney is called the:`, ch:[`Alveolus`,`Nephron`,`Neuron`,`Villus`], ans:1, exp:`Each kidney contains roughly a million nephrons, the microscopic structures that filter blood and form urine.` },
      { q:`Which organ temporarily stores urine before it is released from the body?`, ch:[`The liver`,`The pancreas`,`The urinary bladder`,`The gallbladder`], ans:2, exp:`The urinary bladder is a muscular, expandable sac that stores urine until it is convenient to urinate.` },
      { q:`Besides filtering waste, the kidneys also help regulate the body's:`, ch:[`Vision`,`Hearing`,`Digestion of fats`,`Water balance and blood pressure`], ans:3, exp:`The kidneys help maintain fluid balance, electrolyte levels, and blood pressure by adjusting how much water and salt are excreted or retained.` },
      { q:`Which waste product, formed from protein breakdown, is filtered out of the blood by the kidneys and excreted in urine?`, ch:[`Urea`,`Glucose (in healthy individuals)`,`Oxygen`,`Starch`], ans:0, exp:`Urea is a nitrogen-containing waste product formed when the body breaks down proteins, and it is filtered from the blood and excreted in urine.` },
      { q:`Approximately how many kidneys does a healthy human typically have?`, ch:[`One`,`Two`,`Three`,`Four`], ans:1, exp:`Humans normally have two kidneys, one on each side of the spine, located toward the back of the abdominal cavity.` },
      { q:`Which of the following is NOT a normal function of the urinary system?`, ch:[`Removing metabolic waste from the blood`,`Helping maintain fluid balance`,`Producing digestive enzymes for the stomach`,`Regulating electrolyte levels`], ans:2, exp:`Producing digestive enzymes is a function of organs like the stomach and pancreas, not the urinary system, which focuses on filtering blood and forming urine.` },
      { q:`Blood enters the kidney through a large blood vessel called the:`, ch:[`Pulmonary vein`,`Aorta directly with no branching`,`Portal vein`,`Renal artery`], ans:3, exp:`The renal artery branches off the aorta and delivers blood to each kidney for filtration.` },
      { q:`The color of urine is mainly due to a pigment called:`, ch:[`Urochrome`,`Melanin`,`Hemoglobin`,`Chlorophyll`], ans:0, exp:`Urochrome is a yellow pigment, a breakdown product of hemoglobin, that gives urine its characteristic yellow color.` },
    ]
  },
  {
    id:`bb104`, cat:`Life Sciences`, title:`The Integumentary System (Skin) Basics`, diff:`Easy`,
    qs:[
      { q:`Which of the following is the largest organ of the human body?`, ch:[`The liver`,`The brain`,`The lungs`,`The skin`], ans:3, exp:`The skin is the body's largest organ by surface area and weight, covering and protecting the entire body.` },
      { q:`The skin helps protect the body primarily by:`, ch:[`Acting as a barrier against pathogens, injury, and water loss`,`Producing red blood cells`,`Filtering waste from the blood`,`Digesting nutrients`], ans:0, exp:`The skin forms a physical barrier that keeps out pathogens and harmful substances while preventing excessive loss of water from the body.` },
      { q:`Which layer of the skin is the outermost and contains no blood vessels?`, ch:[`The dermis`,`The epidermis`,`The hypodermis (subcutaneous layer)`,`The dermis and hypodermis together`], ans:1, exp:`The epidermis is the thin, outermost layer of skin. It lacks blood vessels and relies on diffusion from the dermis below for nutrients.` },
      { q:`Sweat glands help regulate body temperature mainly through:`, ch:[`Producing heat directly`,`Absorbing sunlight`,`Evaporative cooling as sweat evaporates from the skin`,`Trapping air near the skin`], ans:2, exp:`As sweat evaporates from the surface of the skin, it removes heat from the body, helping cool it down when body temperature rises.` },
      { q:`Melanin, the pigment that gives skin its color and helps protect against UV radiation, is produced by cells called:`, ch:[`Keratinocytes`,`Fibroblasts`,`Adipocytes`,`Melanocytes`], ans:3, exp:`Melanocytes are specialized cells in the epidermis that produce melanin, which colors the skin and helps absorb harmful UV radiation.` },
      { q:`Which layer of skin contains most of the fat storage, nerve endings, and blood vessels, lying beneath the epidermis?`, ch:[`The dermis`,`The stratum corneum`,`The cuticle`,`The follicle`], ans:0, exp:`The dermis, located beneath the epidermis, contains blood vessels, nerve endings, hair follicles, and glands, and connects to fatty tissue below.` },
      { q:`Hair and nails are both made largely of a tough protein called:`, ch:[`Collagen`,`Keratin`,`Elastin`,`Melanin`], ans:1, exp:`Keratin is a strong, fibrous protein that forms the structural basis of hair, nails, and the outer layer of skin.` },
      { q:`One important role of the skin in vitamin production is that it:`, ch:[`Produces vitamin C when exposed to sunlight`,`Stores vitamin B12`,`Synthesizes vitamin D when exposed to sunlight`,`Produces vitamin A directly from sweat`], ans:2, exp:`When exposed to UV light from the sun, the skin can synthesize vitamin D, which is important for bone health and calcium absorption.` },
      { q:`Which of these is a function of the sense receptors found in the skin?`, ch:[`Filtering blood`,`Producing hormones for growth`,`Regulating heart rate`,`Detecting touch, pressure, pain, and temperature`], ans:3, exp:`The skin contains many nerve endings and specialized receptors that allow it to sense touch, pressure, pain, and changes in temperature.` },
      { q:`Sebaceous glands in the skin primarily produce:`, ch:[`An oily substance (sebum) that lubricates skin and hair`,`Sweat for cooling`,`Melanin for pigmentation`,`Keratin for the nail bed`], ans:0, exp:`Sebaceous glands secrete an oily substance called sebum, which helps keep skin and hair lubricated and somewhat waterproof.` },
      { q:`When the body is cold, tiny muscles attached to hair follicles contract, causing hair to stand up. This response is known as:`, ch:[`Vasodilation`,`The goosebump (piloerection) response`,`Sweating`,`Melanin synthesis`], ans:1, exp:`Piloerection, commonly called goosebumps, occurs when tiny arrector pili muscles contract, pulling hairs upright, an old response that helped trap heat.` },
    ]
  },
  {
    id:`bb105`, cat:`Life Sciences`, title:`The Senses: Sight, Hearing, Taste, Smell & Touch`, diff:`Easy`,
    qs:[
      { q:`Light entering the eye is focused onto the:`, ch:[`Retina`,`Cornea`,`Iris`,`Pupil`], ans:0, exp:`The retina, located at the back of the eye, contains light-sensitive cells that convert focused light into nerve signals sent to the brain.` },
      { q:`Which part of the eye controls the amount of light entering by changing the size of the pupil?`, ch:[`The lens`,`The retina`,`The iris`,`The optic nerve`], ans:2, exp:`The iris is the colored, muscular part of the eye that adjusts the size of the pupil to control how much light enters.` },
      { q:`Sound waves are converted into nerve signals in which part of the ear?`, ch:[`The outer ear`,`The cochlea (inner ear)`,`The eardrum`,`The ear canal`], ans:1, exp:`The cochlea, a fluid-filled spiral structure in the inner ear, contains hair cells that convert sound vibrations into electrical nerve signals.` },
      { q:`The sense of taste is detected primarily by receptors called:`, ch:[`Rods and cones`,`Olfactory receptors`,`Pacinian corpuscles`,`Taste buds`], ans:3, exp:`Taste buds, found mostly on the tongue, contain receptor cells that detect chemicals in food and send taste signals to the brain.` },
      { q:`Which of the following is one of the five commonly recognized basic tastes?`, ch:[`Umami`,`Spicy`,`Metallic`,`Minty`], ans:0, exp:`The five basic tastes commonly recognized are sweet, sour, salty, bitter, and umami (a savory taste associated with amino acids like glutamate).` },
      { q:`The sense of smell relies on receptors located in the:`, ch:[`Tongue`,`Cornea`,`Nasal cavity (olfactory epithelium)`,`Outer ear`], ans:2, exp:`Smell receptors are located in the olfactory epithelium high in the nasal cavity, where they detect airborne chemical molecules.` },
      { q:`Receptors in the skin that detect pressure, vibration, and touch are part of which sense?`, ch:[`Vision`,`Touch (somatosensation)`,`Taste`,`Smell`], ans:1, exp:`Touch, or somatosensation, relies on various receptors in the skin that detect pressure, vibration, texture, and temperature.` },
      { q:`Which structure in the eye bends (refracts) light and can change shape to focus on near or far objects?`, ch:[`The retina`,`The sclera`,`The pupil`,`The lens`], ans:3, exp:`The lens sits behind the pupil and changes shape (a process called accommodation) to focus light from objects at different distances onto the retina.` },
      { q:`Nerve signals from the retina are carried to the brain by the:`, ch:[`Optic nerve`,`Auditory nerve`,`Olfactory nerve`,`Spinal nerve`], ans:0, exp:`The optic nerve transmits visual information collected by the retina to the brain, where it is processed into the images we perceive.` },
      { q:`The three small bones in the middle ear that transmit vibrations are collectively called the:`, ch:[`Cochlear bones`,`Semicircular canals`,`Ossicles (malleus, incus, stapes)`,`Auricle bones`], ans:2, exp:`The malleus, incus, and stapes are the three tiny bones (ossicles) of the middle ear that amplify and transmit sound vibrations to the inner ear.` },
      { q:`Which sense organ also plays a major role in maintaining balance, using fluid-filled canals?`, ch:[`The eye`,`The inner ear`,`The tongue`,`The nose`], ans:1, exp:`The inner ear contains semicircular canals filled with fluid that detect head movement and rotation, helping the body maintain balance.` },
    ]
  },
  {
    id:`bb106`, cat:`Life Sciences`, title:`Blood Types & Transfusion Basics`, diff:`Easy`,
    qs:[
      { q:`The ABO blood typing system classifies blood based on the presence of which molecules on red blood cells?`, ch:[`Hemoglobin variants`,`A and/or B antigens`,`White blood cell markers`,`Platelet proteins`], ans:1, exp:`The ABO system classifies blood by whether red blood cells carry the A antigen, the B antigen, both, or neither, giving types A, B, AB, or O.` },
      { q:`A person with type O blood has which antigens on their red blood cells?`, ch:[`Only the A antigen`,`Only the B antigen`,`Both A and B antigens`,`Neither A nor B antigen`], ans:3, exp:`Type O blood lacks both the A and B antigens on its red blood cells, which is why it is a common donor type.` },
      { q:`Which blood type is often called the 'universal donor' because it can typically be given to patients of any ABO/Rh type in emergencies?`, ch:[`O negative`,`AB positive`,`A negative`,`B positive`], ans:0, exp:`O negative blood lacks A, B, and Rh antigens, so it generally does not trigger an ABO or Rh-based immune reaction, making it useful in emergencies.` },
      { q:`Which blood type is often called the 'universal recipient'?`, ch:[`O negative`,`A positive`,`AB positive`,`B negative`], ans:2, exp:`AB positive individuals have A, B, and Rh antigens already present on their own cells, so they can typically receive blood from any ABO/Rh type.` },
      { q:`The Rh factor refers to:`, ch:[`The number of white blood cells in a sample`,`The presence or absence of a specific protein (Rh antigen) on red blood cells`,`The thickness of blood plasma`,`The percentage of platelets in blood`], ans:1, exp:`The Rh factor is a protein that may or may not be present on red blood cells, giving rise to Rh-positive or Rh-negative blood types.` },
      { q:`Why is it dangerous to transfuse mismatched ABO blood types (e.g., giving type A blood to a type B recipient)?`, ch:[`The blood will clot instantly in the bag`,`It has no real effect on the body`,`It lowers blood pressure permanently`,`The recipient's immune system may attack the donor cells, causing a dangerous reaction`], ans:3, exp:`If blood types are mismatched, the recipient's antibodies can recognize the donor red blood cells as foreign and attack them, causing a potentially life-threatening transfusion reaction.` },
      { q:`Antibodies against A and/or B antigens are naturally found in the plasma of individuals who:`, ch:[`Lack that particular antigen on their own red blood cells`,`Have both A and B antigens`,`Are universal donors only`,`Have Rh-negative blood only`], ans:0, exp:`People naturally produce antibodies against whichever ABO antigens they do not have on their own red blood cells (for example, type A individuals have anti-B antibodies).` },
      { q:`Before a blood transfusion, hospitals perform cross-matching mainly to:`, ch:[`Measure the patient's blood pressure`,`Determine the patient's cholesterol level`,`Ensure donor and recipient blood are compatible and prevent reactions`,`Count the number of red blood cells`], ans:2, exp:`Cross-matching tests donor and recipient blood together in advance to confirm compatibility and avoid a harmful immune reaction during transfusion.` },
      { q:`A pregnant woman who is Rh-negative carrying an Rh-positive baby may need special monitoring because:`, ch:[`Rh factor affects the baby's eye color`,`Her immune system could produce antibodies against the baby's Rh-positive blood cells`,`It always results in blood type O babies`,`It has no medical significance`], ans:1, exp:`If an Rh-negative mother is exposed to Rh-positive fetal blood, she may develop antibodies that could affect a future Rh-positive pregnancy, so doctors monitor and treat this with medication.` },
      { q:`Roughly what percentage of the population has type O blood (combined O+ and O-), making it relatively common?`, ch:[`Less than 1%`,`Around 5%`,`Around 20%`,`Nearly half`], ans:3, exp:`Type O blood (O positive and O negative combined) is the most common blood type in many populations, making up close to half of people.` },
      { q:`Blood plasma, the liquid portion of blood, is composed mostly of:`, ch:[`Water`,`Red blood cells`,`Fat`,`Platelets`], ans:0, exp:`Plasma is roughly 90 percent water, with the remainder made up of proteins, salts, nutrients, hormones, and waste products dissolved or suspended in it.` },
    ]
  },
  {
    id:`bb107`, cat:`Life Sciences`, title:`Vaccines & How Immunity Works`, diff:`Easy`,
    qs:[
      { q:`Vaccines work by:`, ch:[`Directly killing bacteria and viruses already in the body`,`Replacing damaged cells with healthy ones`,`Training the immune system to recognize a pathogen without causing full-blown disease`,`Permanently altering a person's DNA`], ans:2, exp:`Vaccines expose the immune system to a harmless piece or weakened version of a pathogen, prompting the body to build defenses without causing serious illness.` },
      { q:`Cells of the immune system that 'remember' a pathogen after first exposure (including vaccination), allowing a faster response next time, are called:`, ch:[`Memory cells`,`Red blood cells`,`Platelets`,`Skin cells`], ans:0, exp:`Memory cells persist in the body after an infection or vaccination and allow the immune system to respond much faster if the same pathogen appears again.` },
      { q:`A protein produced by the immune system that specifically recognizes and binds to a pathogen is called a(n):`, ch:[`Enzyme`,`Hormone`,`Antigen`,`Antibody`], ans:3, exp:`Antibodies are Y-shaped proteins produced by immune cells that specifically bind to antigens on pathogens, marking them for destruction.` },
      { q:`The substance on a pathogen's surface that the immune system recognizes as foreign is called a(n):`, ch:[`Antibody`,`Antigen`,`Vaccine`,`Vector`], ans:1, exp:`An antigen is any molecule, often on the surface of a pathogen, that the immune system identifies as foreign and responds to.` },
      { q:`'Herd immunity' refers to a situation where:`, ch:[`Only farm animals are protected from disease`,`A single vaccinated person is fully protected forever`,`Enough of a population is immune that disease spread is significantly slowed, protecting even unvaccinated individuals`,`Vaccines are given only to newborns`], ans:2, exp:`When a large enough portion of a population is immune, disease has a harder time spreading, which indirectly helps protect those who cannot be vaccinated.` },
      { q:`Some vaccines use a weakened or inactivated form of a pathogen. This approach is designed to:`, ch:[`Trigger an immune response without causing the actual disease`,`Cure an active infection immediately`,`Provide nutrients to the immune system`,`Replace the need for white blood cells`], ans:0, exp:`Weakened or inactivated pathogens in a vaccine can still be recognized by the immune system, prompting protective immunity, without being able to cause the full disease.` },
      { q:`White blood cells that engulf and digest pathogens and debris are called:`, ch:[`Erythrocytes`,`Platelets`,`Neurons`,`Phagocytes`], ans:3, exp:`Phagocytes, such as macrophages and neutrophils, are white blood cells that engulf and break down pathogens, damaged cells, and debris.` },
      { q:`The first time the body encounters a new pathogen, the immune response is typically:`, ch:[`Instant and identical to future responses`,`Slower, since specific antibodies must first be produced`,`Nonexistent`,`Only handled by the skin`], ans:1, exp:`During a first exposure, the immune system takes time to identify the pathogen and produce specific antibodies, which is why symptoms often appear before immunity develops.` },
      { q:`Which of the following best describes 'active immunity' gained from either infection or vaccination?`, ch:[`Immunity that lasts only a few hours`,`Immunity passed from mother to infant through breast milk`,`Immunity where the body produces its own antibodies and memory cells`,`Immunity created only by antibiotics`], ans:2, exp:`Active immunity develops when the body's own immune system produces antibodies and memory cells in response to a pathogen or vaccine, often providing long-lasting protection.` },
      { q:`A newborn temporarily receiving antibodies from its mother (via placenta or breast milk) is an example of:`, ch:[`Passive immunity`,`Active immunity`,`Autoimmunity`,`Herd immunity`], ans:0, exp:`Passive immunity occurs when antibodies are transferred from one individual to another, such as from mother to baby, providing temporary protection.` },
      { q:`Which of the following is a benefit of widespread vaccination programs in a population?`, ch:[`Elimination of the need for a healthy diet`,`Guaranteed lifetime immunity to all diseases`,`Complete replacement of the immune system`,`Reduced spread of infectious disease and fewer severe outbreaks`], ans:3, exp:`Widespread vaccination reduces how easily a disease can spread through a population, lowering rates of infection and preventing large outbreaks.` },
    ]
  },
  {
    id:`bb108`, cat:`Life Sciences`, title:`Bacteria, Viruses & Fungi: An Intro to Microbes`, diff:`Easy`,
    qs:[
      { q:`Which of the following is a key structural difference between bacteria and human cells?`, ch:[`Bacteria have a nucleus, human cells do not`,`Bacteria have mitochondria, human cells do not`,`Bacteria are always larger than human cells`,`Bacteria are prokaryotic (no nucleus), while human cells are eukaryotic (have a nucleus)`], ans:3, exp:`Bacteria are prokaryotes, meaning their DNA floats freely in the cell rather than being enclosed in a nucleus, unlike eukaryotic human cells.` },
      { q:`Viruses differ from bacteria in that viruses:`, ch:[`Always contain a full set of organelles`,`Cannot reproduce on their own and require a host cell`,`Are visible without a microscope`,`Are a type of fungus`], ans:1, exp:`Viruses are not considered fully living organisms on their own because they lack the machinery to reproduce independently and must hijack a host cell to make copies of themselves.` },
      { q:`Which of these is an example of a beneficial use of microbes for humans?`, ch:[`Causing tooth decay`,`Spoiling food`,`Fermenting milk into yogurt using bacteria`,`Causing the common cold`], ans:2, exp:`Certain beneficial bacteria are intentionally used to ferment milk into yogurt, a process that also occurs in making cheese, sauerkraut, and other foods.` },
      { q:`Fungi obtain nutrients by:`, ch:[`Absorbing nutrients from their environment, often by breaking down organic matter`,`Performing photosynthesis like plants`,`Capturing sunlight directly for energy`,`Producing nutrients through respiration alone`], ans:0, exp:`Unlike plants, fungi cannot photosynthesize. Instead, they absorb nutrients from their surroundings, often by secreting enzymes that break down organic material.` },
      { q:`Which of the following is an example of a fungal organism?`, ch:[`E. coli`,`Influenza virus`,`Salmonella`,`Yeast`], ans:3, exp:`Yeast is a single-celled fungus commonly used in baking and brewing, and it is also studied as a model organism in biology.` },
      { q:`Antibiotics are effective against bacterial infections but generally do NOT work against:`, ch:[`Bacterial pneumonia`,`Viral infections such as the common cold`,`Strep throat`,`Bacterial ear infections`], ans:1, exp:`Antibiotics target structures and processes specific to bacteria and have no effect on viruses, which is why they cannot cure viral illnesses like colds or the flu.` },
      { q:`A pathogen is best defined as:`, ch:[`Any single-celled organism`,`A beneficial microbe used in food production`,`An organism or agent that causes disease`,`A type of human cell`], ans:2, exp:`A pathogen is any organism or infectious agent, such as certain bacteria, viruses, or fungi, capable of causing disease in a host.` },
      { q:`Which of these microbes is generally the smallest, often requiring an electron microscope to see?`, ch:[`Viruses`,`Bacteria`,`Fungi`,`Protozoa`], ans:0, exp:`Viruses are typically far smaller than bacteria, fungi, or protozoa, and their fine structural details usually require an electron microscope to observe.` },
      { q:`Decomposer fungi play an important ecological role by:`, ch:[`Producing oxygen for the atmosphere`,`Hunting and consuming live animals`,`Preventing all bacterial growth`,`Breaking down dead organic material and recycling nutrients`], ans:3, exp:`Many fungi act as decomposers, breaking down dead plants and animals and returning nutrients to the soil for other organisms to use.` },
      { q:`Which structure, found in many bacteria but not in human cells, provides shape and protection?`, ch:[`Nucleus`,`Cell wall`,`Mitochondria`,`Golgi apparatus`], ans:1, exp:`Most bacteria have a rigid cell wall outside their cell membrane that provides shape and structural protection, a feature absent in human cells.` },
      { q:`Which of the following best describes how a virus reproduces?`, ch:[`It divides by binary fission like bacteria`,`It photosynthesizes to create energy for replication`,`It hijacks a host cell's machinery to make copies of itself`,`It reproduces sexually with another virus`], ans:2, exp:`Viruses cannot reproduce independently; they must infect a host cell and use that cell's machinery to replicate their genetic material and produce new viral particles.` },
    ]
  },
  {
    id:`bb109`, cat:`Life Sciences`, title:`Antibiotic Resistance Basics`, diff:`Medium`,
    qs:[
      { q:`Antibiotic resistance occurs when:`, ch:[`Bacteria evolve mechanisms that allow them to survive exposure to antibiotics that once killed them`,`A person becomes immune to bacteria permanently`,`Antibiotics change into a different chemical compound`,`Viruses become resistant to antiviral drugs`], ans:0, exp:`Antibiotic resistance refers to bacteria developing genetic changes that let them survive and grow even in the presence of antibiotics that would normally kill them.` },
      { q:`Which of the following practices contributes MOST to the spread of antibiotic resistance?`, ch:[`Taking the full prescribed course of antibiotics`,`Overuse and misuse of antibiotics, such as not finishing a prescription or using them for viral infections`,`Washing hands regularly`,`Using vaccines to prevent infection`], ans:1, exp:`Overusing or misusing antibiotics, including stopping treatment early or taking them unnecessarily for viral illnesses, increases the chances that resistant bacteria survive and spread.` },
      { q:`Antibiotic resistance in a bacterial population is an example of which broader biological process?`, ch:[`Genetic engineering`,`Photosynthesis`,`Osmosis`,`Natural selection`], ans:3, exp:`Antibiotic resistance is a real-world example of natural selection: bacteria with resistance traits survive antibiotic exposure and reproduce, while susceptible bacteria are killed off.` },
      { q:`If a course of antibiotics kills most bacteria but a few survive due to resistance genes, those survivors can:`, ch:[`Immediately die from lack of competition`,`Lose their resistance genes over time automatically`,`Reproduce and pass resistance traits to future generations`,`Turn into a completely different species`], ans:2, exp:`Surviving resistant bacteria can multiply rapidly and pass their resistance genes on, allowing a resistant population to grow over time.` },
      { q:`Which of the following is a reason antibiotics are NOT effective against viral illnesses like the flu?`, ch:[`Antibiotics target structures and processes specific to bacteria, which viruses do not have`,`Viruses are too large for antibiotics to reach`,`Antibiotics only work on fungi`,`Viruses are immune to all chemicals`], ans:0, exp:`Antibiotics work by targeting bacterial structures or processes, such as cell walls, that viruses simply do not have, making antibiotics useless against viral infections.` },
      { q:`'Superbugs' is a term commonly used to describe:`, ch:[`Extremely large insects that spread disease`,`Bacterial strains that have become resistant to multiple antibiotics`,`Viruses that mutate quickly`,`A type of beneficial probiotic bacteria`], ans:1, exp:`Superbugs are strains of bacteria that have developed resistance to multiple antibiotics, making infections with them especially difficult to treat.` },
      { q:`One way resistance genes can spread between different bacteria (even different species) is through:`, ch:[`Photosynthesis`,`Binary fission alone`,`Direct injection by white blood cells`,`Horizontal gene transfer, such as passing plasmids between bacteria`], ans:3, exp:`Bacteria can exchange small circular pieces of DNA called plasmids with one another, a process called horizontal gene transfer, which can spread resistance genes even between different species.` },
      { q:`Public health experts recommend which of the following to help slow the development of antibiotic resistance?`, ch:[`Prescribing antibiotics for every minor illness`,`Stopping antibiotics as soon as symptoms improve, even if not finished`,`Using antibiotics only when necessary and completing the full prescribed course`,`Sharing leftover antibiotics with family members`], ans:2, exp:`Using antibiotics only when truly needed, and completing the full prescribed course, helps reduce the chances that resistant bacteria survive and spread.` },
      { q:`Why is it a problem for hospitals when a bacterial infection becomes resistant to first-line antibiotics?`, ch:[`Doctors may need to use stronger, more expensive, or less available drugs, and infections can be harder to treat`,`It means the infection is no longer contagious`,`It means the bacteria will die out naturally`,`It has no practical impact on patient care`], ans:0, exp:`When common antibiotics stop working, doctors must turn to alternative drugs that may be more costly, have more side effects, or be less readily available, making treatment more difficult.` },
      { q:`Which of these best explains why finishing a full course of prescribed antibiotics is important?`, ch:[`It saves money on future prescriptions`,`Stopping early may leave the hardiest bacteria alive, which can multiply and be harder to treat`,`It has no effect on treatment outcomes`,`It only matters for viral infections`], ans:1, exp:`Stopping antibiotics early can leave behind the most resistant bacteria, which survived the partial treatment and can then multiply, potentially making future infections harder to treat.` },
      { q:`Antibiotic use in livestock and agriculture, when not carefully controlled, can contribute to resistance because:`, ch:[`Animals cannot develop bacterial infections`,`It has been scientifically shown to have zero effect on human health`,`Antibiotics used on farms are chemically different from those used in humans`,`Resistant bacteria that develop in animals can potentially spread to humans through food or the environment`], ans:3, exp:`Widespread antibiotic use in agriculture can promote resistant bacteria in animals, and these resistant strains can sometimes spread to humans through food, water, or direct contact.` },
    ]
  },
  {
    id:`bb110`, cat:`Life Sciences`, title:`Plant Biology: Structure & Function`, diff:`Easy`,
    qs:[
      { q:`Which plant structure is primarily responsible for absorbing water and minerals from the soil?`, ch:[`Leaves`,`Roots`,`Flowers`,`Stems`], ans:1, exp:`Roots anchor the plant in soil and are specialized to absorb water and dissolved minerals, often aided by tiny root hairs that increase surface area.` },
      { q:`The process by which plants use sunlight, water, and carbon dioxide to produce glucose and oxygen is called:`, ch:[`Respiration`,`Transpiration`,`Photosynthesis`,`Germination`], ans:2, exp:`Photosynthesis is the process plants use to convert light energy, water, and carbon dioxide into glucose (for energy) and oxygen as a byproduct.` },
      { q:`Which structure in plant cells contains chlorophyll and is the primary site of photosynthesis?`, ch:[`Chloroplast`,`Mitochondrion`,`Nucleus`,`Vacuole`], ans:0, exp:`Chloroplasts contain the green pigment chlorophyll, which captures light energy and is where the reactions of photosynthesis take place.` },
      { q:`Tiny pores on the underside of leaves that allow gas exchange (CO2 in, O2/water vapor out) are called:`, ch:[`Chloroplasts`,`Xylem vessels`,`Root hairs`,`Stomata`], ans:3, exp:`Stomata are small pores, usually on the underside of leaves, that open and close to regulate the exchange of gases and water vapor with the atmosphere.` },
      { q:`Which plant tissue transports water and dissolved minerals from the roots up to the leaves?`, ch:[`Phloem`,`Xylem`,`Epidermis`,`Cortex`], ans:1, exp:`Xylem is the plant tissue that carries water and dissolved minerals upward from the roots to the stems and leaves.` },
      { q:`Which plant tissue transports sugars (produced by photosynthesis) from the leaves to other parts of the plant?`, ch:[`Xylem`,`Cambium`,`Phloem`,`Epidermis`], ans:2, exp:`Phloem transports sugars made during photosynthesis from the leaves to other parts of the plant that need energy, such as roots and growing tissues.` },
      { q:`The loss of water vapor from leaves, mainly through stomata, is called:`, ch:[`Transpiration`,`Germination`,`Pollination`,`Fertilization`], ans:0, exp:`Transpiration is the evaporation of water vapor from a plant's leaves, mainly through stomata, which also helps draw water up from the roots.` },
      { q:`Which part of the plant typically produces seeds after fertilization occurs?`, ch:[`Root`,`Stem`,`Leaf`,`Flower (ovary)`], ans:3, exp:`After fertilization, the ovary within a flower develops into a fruit containing seeds, which can grow into new plants.` },
      { q:`Plant cells, unlike animal cells, have a rigid outer layer that provides structural support called the:`, ch:[`Plasma membrane`,`Cell wall`,`Nuclear envelope`,`Cytoskeleton`], ans:1, exp:`The cell wall is a rigid layer made mainly of cellulose that surrounds plant cells, providing structural support and shape, unlike animal cells which lack it.` },
      { q:`A large, membrane-bound sac in plant cells that stores water and helps maintain the cell's rigidity (turgor pressure) is the:`, ch:[`Chloroplast`,`Ribosome`,`Central vacuole`,`Golgi apparatus`], ans:2, exp:`The central vacuole stores water and other substances, and the pressure it exerts against the cell wall (turgor pressure) helps keep plant cells and structures rigid.` },
      { q:`Which gas do plants take in from the atmosphere during photosynthesis?`, ch:[`Carbon dioxide`,`Oxygen`,`Nitrogen`,`Hydrogen`], ans:0, exp:`Plants absorb carbon dioxide from the air through their stomata and use it, along with water and light energy, to produce glucose during photosynthesis.` },
    ]
  },
  {
    id:`bb111`, cat:`Life Sciences`, title:`Plant Reproduction & Life Cycles`, diff:`Easy`,
    qs:[
      { q:`In a flowering plant, the male reproductive structure that produces pollen is the:`, ch:[`Pistil`,`Ovary`,`Stamen`,`Sepal`], ans:2, exp:`The stamen is the male part of a flower, consisting of a filament and an anther, and it is where pollen grains are produced.` },
      { q:`The female reproductive structure of a flower, which contains the ovary, is called the:`, ch:[`Stamen`,`Anther`,`Petal`,`Pistil`], ans:3, exp:`The pistil is the female reproductive structure of a flower, made up of the stigma, style, and ovary, where eggs are produced and fertilized.` },
      { q:`The transfer of pollen from the male part of a flower to the female part is called:`, ch:[`Germination`,`Pollination`,`Fertilization`,`Photosynthesis`], ans:1, exp:`Pollination is the process of moving pollen from the anther (male part) to the stigma (female part) of a flower, often with help from wind or animals.` },
      { q:`After fertilization, the ovule of a flower typically develops into a:`, ch:[`Seed`,`Root`,`Petal`,`Stem`], ans:0, exp:`Once fertilized, an ovule develops into a seed, which contains a young embryo plant along with stored nutrients.` },
      { q:`Which of the following is a common method of seed dispersal in nature?`, ch:[`Photosynthesis`,`Osmosis`,`Wind carrying lightweight seeds away from the parent plant`,`Cell division within the seed itself`], ans:2, exp:`Many plants have seeds adapted to be carried by wind, such as the winged seeds of maple trees, helping the seeds spread away from the parent plant.` },
      { q:`Many flowering plants rely on animals such as bees for:`, ch:[`Producing chlorophyll`,`Absorbing water through roots`,`Performing photosynthesis`,`Carrying pollen between flowers`], ans:3, exp:`Bees and other pollinators visit flowers for nectar and inadvertently carry pollen from one flower to another, enabling fertilization.` },
      { q:`Which of the following is an example of asexual (vegetative) plant reproduction?`, ch:[`A bee pollinating two different flowers`,`A strawberry plant growing new plants from runners (stolons)`,`Pollen fertilizing an egg cell`,`A seed germinating after fertilization`], ans:1, exp:`Some plants, like strawberries, can reproduce asexually by growing runners (stolons) that form new, genetically identical plants without fertilization.` },
      { q:`Germination refers to the process in which:`, ch:[`A seed begins to grow into a new plant`,`Pollen is produced`,`A flower wilts and dies`,`Roots absorb minerals`], ans:0, exp:`Germination is the process by which a seed, given the right conditions of water, temperature, and oxygen, begins to sprout and grow into a new plant.` },
      { q:`A fruit, botanically speaking, develops from the:`, ch:[`Stem of the plant`,`Petals of the flower`,`Ripened ovary of a flower`,`Roots of the plant`], ans:2, exp:`After fertilization, the ovary of a flower matures and develops into a fruit, which surrounds and protects the developing seeds.` },
      { q:`Some plants, like ferns, reproduce using structures released into the environment called:`, ch:[`Seeds`,`Fruits`,`Flowers`,`Spores`], ans:3, exp:`Ferns and some other plants do not produce flowers or seeds; instead, they reproduce using spores, which can develop into new plants under the right conditions.` },
      { q:`Which of the following best explains why flowers often have bright colors and scents?`, ch:[`To protect against frost`,`To attract pollinators such as insects and birds`,`To absorb more sunlight for photosynthesis`,`To store extra water`], ans:1, exp:`Bright colors and pleasant scents in flowers help attract pollinators like bees, butterflies, and birds, increasing the chances of successful pollination.` },
    ]
  },
  {
    id:`bb112`, cat:`Life Sciences`, title:`Homeostasis & Feedback Loops`, diff:`Easy`,
    qs:[
      { q:`Homeostasis refers to an organism's ability to:`, ch:[`Grow continuously without limit`,`Reproduce asexually`,`Convert light energy into chemical energy`,`Maintain a stable internal environment despite external changes`], ans:3, exp:`Homeostasis is the ability of an organism to keep internal conditions, such as temperature or blood sugar, relatively stable even when the external environment changes.` },
      { q:`Which of the following is a classic example of homeostasis in the human body?`, ch:[`Maintaining a stable internal body temperature around 37°C (98.6°F)`,`Growing taller during puberty`,`Digesting a meal`,`Producing new skin cells after a cut`], ans:0, exp:`The human body works to keep its internal temperature near 37°C regardless of outside temperature, a well-known example of homeostatic regulation.` },
      { q:`In a negative feedback loop, the body's response to a change is to:`, ch:[`Amplify the original change further and further`,`Ignore the change completely`,`Counteract the change and return conditions toward a normal set point`,`Permanently alter the set point`], ans:2, exp:`Negative feedback loops work to reverse or counteract a change, bringing a variable like temperature or blood sugar back toward its normal set point.` },
      { q:`Which of the following is an example of a negative feedback loop?`, ch:[`Contractions during childbirth becoming stronger and more frequent`,`Shivering to generate heat when body temperature drops too low`,`Blood clotting cascading to seal a wound`,`A fever escalating rapidly without any control`], ans:1, exp:`Shivering is a negative feedback response: when body temperature drops below normal, muscle contractions generate heat to bring temperature back up toward normal.` },
      { q:`Positive feedback loops differ from negative feedback loops in that positive feedback:`, ch:[`Always maintains a constant internal state`,`Is the most common type of regulation in the body`,`Slows down or reverses a process`,`Amplifies a change rather than reversing it`], ans:3, exp:`Positive feedback loops push a process further in the same direction, amplifying a change rather than counteracting it, and are less common than negative feedback in the body.` },
      { q:`Which of these is an example of a positive feedback loop in the human body?`, ch:[`Uterine contractions intensifying during labor until birth occurs`,`Sweating to cool the body when overheated`,`Shivering when cold`,`Insulin lowering blood sugar after a meal`], ans:0, exp:`During childbirth, contractions trigger the release of hormones that cause even stronger contractions, an amplifying positive feedback loop that continues until birth occurs.` },
      { q:`When blood sugar rises after eating, the pancreas releases insulin. This is part of a feedback loop that:`, ch:[`Increases blood sugar even further`,`Has no relation to blood sugar regulation`,`Helps lower blood sugar back toward a normal range`,`Stops the pancreas from functioning`], ans:2, exp:`Insulin release is part of a negative feedback loop: as blood sugar rises, insulin helps cells absorb glucose, bringing blood sugar back down toward a normal range.` },
      { q:`A 'set point' in a homeostatic system refers to:`, ch:[`The maximum possible value a variable can reach`,`The target or normal value that the body tries to maintain`,`A random fluctuation in body chemistry`,`The point at which an organism dies`], ans:1, exp:`A set point is the target value, such as normal body temperature or blood sugar level, that regulatory systems work to maintain or return to.` },
      { q:`Sensors (receptors) in a feedback loop are responsible for:`, ch:[`Directly causing the response`,`Storing long-term memory`,`Producing hormones exclusively`,`Detecting changes in the internal or external environment`], ans:3, exp:`Sensors, or receptors, detect changes in a variable (like temperature) and send that information to a control center, which then triggers an appropriate response.` },
      { q:`Why is homeostasis important for living organisms?`, ch:[`It allows cells and organs to function properly within a stable, narrow range of conditions`,`It allows organisms to grow without any limits`,`It eliminates the need for food or water`,`It prevents all disease`], ans:0, exp:`Cells and organs generally function best within a narrow range of conditions, so homeostasis helps ensure the internal environment stays suitable for normal biological processes.` },
      { q:`If the body's cooling mechanisms (like sweating) fail during a heat wave, body temperature can rise dangerously. This illustrates that homeostasis:`, ch:[`Is guaranteed to succeed under all conditions`,`Only applies to temperature, not other variables`,`Can be overwhelmed if a disturbance is too extreme for the regulatory system to handle`,`Has no real-world importance`], ans:2, exp:`Homeostatic mechanisms have limits; if a disturbance, like extreme heat, is too severe or prolonged, the body's regulatory systems can be overwhelmed, leading to conditions like heat stroke.` },
    ]
  },
  {
    id:`bb113`, cat:`Life Sciences`, title:`Enzymes 101: How Biological Catalysts Work`, diff:`Easy`,
    qs:[
      { q:`Enzymes are best described as:`, ch:[`Biological catalysts that speed up chemical reactions`,`Structural proteins that provide support to cells`,`Molecules that store genetic information`,`A type of carbohydrate used for energy storage`], ans:0, exp:`Enzymes are proteins (or occasionally RNA molecules) that act as biological catalysts, speeding up chemical reactions in living organisms without being used up.` },
      { q:`The specific molecule that an enzyme acts upon is called the:`, ch:[`Cofactor`,`Product`,`Catalyst`,`Substrate`], ans:3, exp:`The substrate is the specific molecule an enzyme binds to and converts into a product during a chemical reaction.` },
      { q:`Enzymes speed up reactions by:`, ch:[`Increasing the amount of substrate available`,`Lowering the activation energy needed for the reaction to occur`,`Adding extra energy to the reactants permanently`,`Changing the products into reactants`], ans:1, exp:`Enzymes speed up reactions by lowering the activation energy barrier, making it easier for a reaction to proceed, without changing the overall energy released or absorbed.` },
      { q:`The region of an enzyme where the substrate binds and the reaction occurs is called the:`, ch:[`Nucleus`,`Cell membrane`,`Active site`,`Ribosome`], ans:2, exp:`The active site is a specifically shaped pocket on the enzyme where the substrate binds, allowing the reaction to be catalyzed.` },
      { q:`Most enzymes are what type of molecule?`, ch:[`Proteins`,`Carbohydrates`,`Lipids`,`Nucleic acids`], ans:0, exp:`Most enzymes are proteins, folded into specific three-dimensional shapes that allow them to bind substrates and catalyze reactions.` },
      { q:`Extreme heat can cause an enzyme to lose its shape and stop functioning. This process is called:`, ch:[`Replication`,`Hydrolysis`,`Fermentation`,`Denaturation`], ans:3, exp:`Denaturation occurs when heat or extreme pH disrupts an enzyme's normal folded structure, causing it to lose its shape and function.` },
      { q:`Each enzyme typically works best on a specific substrate because of the enzyme's:`, ch:[`Color`,`Uniquely shaped active site that fits its substrate`,`Ability to reproduce`,`Location in the nucleus only`], ans:1, exp:`Enzymes are usually specific to one or a few substrates because their active site has a particular shape that fits only certain molecules, similar to a lock and key.` },
      { q:`Which factor generally increases enzyme activity, up to a certain optimal point, after which activity declines?`, ch:[`Removing all substrate`,`Freezing the enzyme solid`,`Increasing temperature toward the enzyme's optimum`,`Exposing the enzyme to extreme pH only`], ans:2, exp:`As temperature rises toward an enzyme's optimal range, reaction rates typically increase, but beyond that optimum, the enzyme can begin to denature and lose activity.` },
      { q:`Enzymes are considered catalysts because they:`, ch:[`Speed up reactions without being permanently consumed or changed`,`Are used up completely in every reaction`,`Only work one time and then disappear`,`Slow down chemical reactions`], ans:0, exp:`A defining feature of catalysts, including enzymes, is that they speed up reactions but are not permanently consumed, so they can be reused for further reactions.` },
      { q:`Which of these human digestive enzymes helps break down starch into simpler sugars, starting in the mouth?`, ch:[`Pepsin`,`Lipase`,`Trypsin`,`Amylase`], ans:3, exp:`Amylase, found in saliva, begins breaking down starch into smaller sugar molecules as soon as food is chewed in the mouth.` },
      { q:`If the pH of an enzyme's environment moves far from its optimal range, the enzyme's activity will typically:`, ch:[`Increase indefinitely`,`Decrease, and the enzyme may eventually denature`,`Stay exactly the same`,`Double in speed`], ans:1, exp:`Each enzyme has an optimal pH range; moving too far from that range can disrupt the enzyme's shape, reducing its activity or causing denaturation.` },
    ]
  },
  {
    id:`bb114`, cat:`Life Sciences`, title:`Cell Cycle & Cancer Basics`, diff:`Medium`,
    qs:[
      { q:`The cell cycle is best described as:`, ch:[`A single continuous process of cell death`,`The series of stages a cell goes through as it grows and divides into two daughter cells`,`A process that only occurs in bacteria`,`The process of protein folding`], ans:1, exp:`The cell cycle refers to the ordered sequence of growth, DNA replication, and division stages that a cell passes through to produce two daughter cells.` },
      { q:`The phase of the cell cycle in which a cell copies its DNA is called:`, ch:[`S phase (synthesis phase)`,`M phase (mitosis)`,`G0 phase`,`Cytokinesis`], ans:0, exp:`During S phase, the cell replicates its entire DNA content so that each resulting daughter cell will receive a complete set of chromosomes.` },
      { q:`Checkpoints in the cell cycle serve to:`, ch:[`Randomly damage DNA`,`Speed up cell division at all costs`,`Prevent any cell from ever dividing`,`Monitor the cell for errors (like DNA damage) before allowing the cycle to proceed`], ans:3, exp:`Checkpoints act as quality-control points, pausing the cell cycle to check for problems such as DNA damage before allowing the cell to continue toward division.` },
      { q:`Cancer can arise when cells:`, ch:[`Divide too slowly`,`Stop dividing permanently`,`Accumulate mutations that cause uncontrolled cell division, ignoring normal regulatory signals`,`Lose their DNA entirely`], ans:2, exp:`Cancer typically develops when a cell accumulates mutations that disable normal regulatory controls, allowing it to divide uncontrollably and ignore signals that would normally stop growth.` },
      { q:`A tumor suppressor gene normally functions to:`, ch:[`Actively promote uncontrolled cell growth`,`Help regulate the cell cycle and prevent excessive cell division`,`Destroy healthy cells randomly`,`Increase the rate of mutation`], ans:1, exp:`Tumor suppressor genes normally act as brakes on the cell cycle, helping prevent cells from dividing too much; when these genes are mutated or lost, cancer risk increases.` },
      { q:`A benign tumor differs from a malignant (cancerous) tumor mainly in that a benign tumor:`, ch:[`Does not invade nearby tissue or spread to other parts of the body`,`Always spreads throughout the body`,`Is made of bacteria rather than cells`,`Cannot be detected by any medical test`], ans:0, exp:`Benign tumors grow locally but generally do not invade surrounding tissue or spread (metastasize) to other parts of the body, unlike malignant tumors.` },
      { q:`The spread of cancer cells from their original site to other parts of the body is called:`, ch:[`Mitosis`,`Apoptosis`,`Mutation`,`Metastasis`], ans:3, exp:`Metastasis is the process by which cancer cells break away from the original tumor and travel through the blood or lymphatic system to form new tumors elsewhere.` },
      { q:`Apoptosis is best described as:`, ch:[`Uncontrolled growth of a cell`,`The process of DNA replication`,`A programmed, controlled process of cell death that removes damaged or unneeded cells`,`A type of cell division`], ans:2, exp:`Apoptosis is a normal, controlled process in which damaged, unnecessary, or potentially dangerous cells are signaled to die, helping the body avoid problems like cancer.` },
      { q:`Cancer cells often differ from normal cells in that they:`, ch:[`Always remain in the G0 (resting) phase`,`Ignore normal signals that would stop cell division and continue dividing`,`Cannot use energy from glucose`,`Have no nucleus`], ans:1, exp:`Cancer cells often lose the ability to respond to normal growth-inhibiting signals, allowing them to continue dividing when a healthy cell would stop.` },
      { q:`Which lifestyle or environmental factor is well established as increasing cancer risk by damaging DNA?`, ch:[`Excessive exposure to UV radiation or tobacco smoke`,`Drinking enough water daily`,`Getting regular moderate exercise`,`Eating a variety of fruits and vegetables`], ans:0, exp:`UV radiation and chemicals in tobacco smoke are well-documented causes of DNA damage that can lead to mutations and increase the risk of cancer over time.` },
      { q:`Why is uncontrolled cell division potentially dangerous for an organism?`, ch:[`It always improves organ function`,`It has no effect on surrounding tissue`,`It only happens in plant cells`,`It can form a mass of cells (tumor) that may damage surrounding tissue or spread to other organs`], ans:3, exp:`Uncontrolled cell division can produce a growing mass of abnormal cells that may crowd out normal tissue, disrupt organ function, and in malignant cases, spread to other parts of the body.` },
    ]
  },
  {
    id:`bb115`, cat:`Life Sciences`, title:`DNA Technology Basics: PCR & Gel Electrophoresis`, diff:`Medium`,
    qs:[
      { q:`PCR (polymerase chain reaction) is a laboratory technique used to:`, ch:[`Sequence an entire genome from scratch`,`Directly view DNA under a light microscope`,`Make many copies of a specific segment of DNA`,`Cut DNA into random fragments`], ans:2, exp:`PCR is used to exponentially amplify a specific, targeted segment of DNA, producing millions of copies from a very small starting sample.` },
      { q:`In PCR, the enzyme responsible for building new strands of DNA is called:`, ch:[`Ligase`,`DNA polymerase (often a heat-stable version like Taq polymerase)`,`Helicase only`,`RNA polymerase`], ans:1, exp:`A heat-stable DNA polymerase, commonly Taq polymerase (from a heat-tolerant bacterium), builds new DNA strands by adding nucleotides during each PCR cycle.` },
      { q:`Short DNA sequences that mark the start and end of the region to be copied in PCR are called:`, ch:[`Primers`,`Codons`,`Introns`,`Ribosomes`], ans:0, exp:`Primers are short, single-stranded DNA sequences that bind to specific complementary sites, marking where DNA polymerase should begin copying the target region.` },
      { q:`PCR requires repeated cycles of heating and cooling mainly because heat is used to:`, ch:[`Destroy contaminating bacteria only`,`Add new primers to the reaction`,`Permanently deactivate the DNA polymerase`,`Separate (denature) the two DNA strands so they can be copied`], ans:3, exp:`High heat is used in each PCR cycle to separate the two strands of the DNA double helix, allowing primers and polymerase to access and copy each single strand.` },
      { q:`Gel electrophoresis is a technique used to:`, ch:[`Amplify DNA fragments before sequencing`,`Destroy unwanted DNA samples`,`Separate DNA fragments by size using an electric current through a gel`,`Directly determine the exact DNA sequence letter by letter`], ans:2, exp:`Gel electrophoresis uses an electric current to pull DNA fragments through a gel matrix, separating them by size, with smaller fragments moving farther.` },
      { q:`In gel electrophoresis, DNA fragments move through the gel toward the positive electrode because DNA is:`, ch:[`Neutral in charge`,`Negatively charged, due to its phosphate backbone`,`Positively charged`,`Magnetic`], ans:1, exp:`DNA's phosphate backbone carries a negative charge, so DNA fragments migrate through the gel toward the positive electrode when an electric current is applied.` },
      { q:`In a gel electrophoresis result, smaller DNA fragments travel:`, ch:[`Farther through the gel than larger fragments in the same amount of time`,`Exactly the same distance as larger fragments`,`Not at all through the gel`,`In the opposite direction of larger fragments`], ans:0, exp:`Smaller DNA fragments move more easily through the pores of the gel matrix, so they travel farther than larger fragments in the same amount of time.` },
      { q:`One common real-world application of PCR combined with gel electrophoresis is:`, ch:[`Directly treating a bacterial infection`,`Replacing the need for a microscope in all labs`,`Growing new organs`,`DNA fingerprinting, such as in forensic investigations or paternity testing`], ans:3, exp:`PCR and gel electrophoresis together are commonly used for DNA fingerprinting, allowing scientists to compare DNA patterns for purposes like forensic identification or paternity testing.` },
      { q:`Why is PCR considered extremely sensitive and useful even with very small starting DNA samples?`, ch:[`It requires a full genome to start`,`It can only be used on RNA`,`It can exponentially amplify a tiny amount of DNA into millions of copies`,`It destroys the original sample entirely with no output`], ans:2, exp:`PCR doubles the amount of target DNA with each cycle, so after many cycles, even a tiny starting sample can be amplified into millions of copies, enough to analyze.` },
      { q:`During PCR, after DNA strands are separated by heat, the mixture is cooled slightly to allow primers to:`, ch:[`Evaporate from the solution`,`Bind (anneal) to their complementary sequences on the DNA`,`Become permanently denatured`,`Turn into DNA polymerase`], ans:1, exp:`Cooling the reaction slightly allows the short primer sequences to bind, or anneal, to their complementary sequences on the separated DNA strands.` },
      { q:`A 'DNA ladder' used alongside samples in gel electrophoresis serves as a:`, ch:[`Reference with fragments of known sizes, used to estimate the size of sample fragments`,`Source of extra primers for the reaction`,`Replacement for DNA polymerase`,`Way to destroy contaminating samples`], ans:0, exp:`A DNA ladder contains fragments of known, established sizes that are run alongside samples, allowing scientists to estimate the size of unknown DNA fragments by comparison.` },
    ]
  },
  {
    id:`bb116`, cat:`Life Sciences`, title:`Genetics Probability: Dihybrid Crosses & Beyond`, diff:`Medium`,
    qs:[
      { q:`A dihybrid cross examines the inheritance of:`, ch:[`No traits at all, only chromosome number`,`One trait controlled by a single gene`,`Traits controlled by genes on the same chromosome only`,`Two different traits, each controlled by a separate gene, simultaneously`], ans:3, exp:`A dihybrid cross tracks how two different traits, each controlled by a separate gene, are inherited together in the offspring of a cross.` },
      { q:`In a classic dihybrid cross between two heterozygous parents (AaBb x AaBb), assuming independent assortment, what phenotypic ratio is expected in the offspring?`, ch:[`1:2:1`,`3:1`,`9:3:3:1`,`1:1:1:1`], ans:2, exp:`For a standard dihybrid cross between two double heterozygotes with independent assortment, the expected phenotypic ratio in offspring is 9:3:3:1.` },
      { q:`The Law of Independent Assortment states that:`, ch:[`All traits are always inherited together`,`Alleles for different genes (typically on different chromosomes) are distributed to gametes independently of one another`,`Only dominant alleles can be passed to offspring`,`Genes never separate during meiosis`], ans:1, exp:`Independent assortment describes how alleles for different genes, usually located on different chromosomes, are distributed into gametes independently during meiosis.` },
      { q:`A Punnett square is a tool used to:`, ch:[`Predict the possible genotype and phenotype combinations of offspring from a genetic cross`,`Directly sequence an organism's DNA`,`Measure the size of chromosomes`,`Determine an organism's exact age`], ans:0, exp:`A Punnett square is a diagram used to predict the possible combinations of alleles, and resulting genotypes and phenotypes, that offspring could inherit from a specific genetic cross.` },
      { q:`If a gene has two possible alleles, and an individual is heterozygous, this individual carries:`, ch:[`Two identical dominant alleles`,`Two identical recessive alleles`,`No alleles for that gene`,`One dominant and one recessive allele`], ans:3, exp:`A heterozygous individual carries two different alleles for a gene, typically one dominant and one recessive.` },
      { q:`Genes located very close together on the same chromosome tend to be inherited together, a phenomenon known as:`, ch:[`Independent assortment`,`Codominance`,`Genetic linkage`,`Incomplete dominance`], ans:2, exp:`Genetic linkage occurs when genes are located close together on the same chromosome, making them more likely to be inherited together rather than assorting independently.` },
      { q:`In incomplete dominance, the heterozygous phenotype:`, ch:[`Is identical to one of the homozygous parent phenotypes`,`Blends or is intermediate between the two homozygous phenotypes`,`Is impossible to observe`,`Always matches the recessive phenotype`], ans:1, exp:`In incomplete dominance, neither allele fully masks the other, so the heterozygous offspring shows a blended or intermediate phenotype, such as pink flowers from red and white parent alleles.` },
      { q:`Codominance occurs when:`, ch:[`Both alleles in a heterozygote are fully and separately expressed in the phenotype`,`One allele completely masks the other`,`Neither allele is expressed`,`The alleles blend into a completely new trait`], ans:0, exp:`In codominance, both alleles are fully expressed at the same time in the heterozygote's phenotype, rather than blending, as seen with AB blood type showing both A and B markers.` },
      { q:`If two parents are each heterozygous for a single trait (Aa x Aa), what is the probability that an offspring will show the recessive phenotype?`, ch:[`0%`,`75%`,`50%`,`25%`], ans:3, exp:`Crossing Aa x Aa gives a 1 AA : 2 Aa : 1 aa genotype ratio, so 1 out of 4 offspring, or 25%, are expected to be homozygous recessive (aa) and show the recessive phenotype.` },
      { q:`For a cross involving two independently assorting genes, the probability of a specific combined genotype can be calculated by:`, ch:[`Adding the individual probabilities together`,`Ignoring one of the two genes`,`Multiplying the individual probabilities of each separate trait (the product rule)`,`Always assuming a 50/50 outcome`], ans:2, exp:`For independently assorting genes, the probability of a specific combined outcome is found by multiplying the individual probabilities of each trait occurring separately, known as the product rule.` },
      { q:`A test cross (crossing an individual of unknown genotype with a homozygous recessive individual) is used to:`, ch:[`Guarantee all offspring show the dominant trait`,`Determine whether the unknown individual is homozygous dominant or heterozygous`,`Eliminate recessive alleles from a population`,`Directly view the individual's DNA sequence`], ans:1, exp:`A test cross helps reveal an unknown genotype: if any offspring show the recessive phenotype, the tested individual must be heterozygous, since a homozygous dominant parent would produce only dominant-phenotype offspring.` },
    ]
  },
  {
    id:`bb117`, cat:`Life Sciences`, title:`Sex-Linked Traits & Pedigrees`, diff:`Medium`,
    qs:[
      { q:`Sex-linked traits are typically controlled by genes located on the:`, ch:[`X chromosome`,`Autosomes only (non-sex chromosomes)`,`Mitochondrial DNA only`,`Y chromosome exclusively for all sex-linked traits`], ans:0, exp:`Most sex-linked traits studied in genetics are carried on the X chromosome, since it is much larger and carries far more genes than the Y chromosome.` },
      { q:`In humans, biological males typically have which sex chromosome combination?`, ch:[`XX`,`XXX`,`XY`,`YY`], ans:2, exp:`Biological males typically have one X and one Y chromosome (XY), while biological females typically have two X chromosomes (XX).` },
      { q:`Why are X-linked recessive traits (such as red-green color blindness) more common in males than in females?`, ch:[`Males have two X chromosomes, doubling their risk`,`Females cannot inherit X-linked traits at all`,`The trait only exists on the Y chromosome`,`Males have only one X chromosome, so a single recessive allele on it will be expressed since there is no second X to mask it`], ans:3, exp:`Because males have only one X chromosome, a single recessive allele on that X will be expressed, whereas females need two copies of the recessive allele (one on each X) to show the trait.` },
      { q:`A female who carries one copy of a recessive X-linked allele (and is phenotypically unaffected) is referred to as a:`, ch:[`Homozygous dominant individual`,`Carrier`,`Hemizygous individual`,`Affected individual`], ans:1, exp:`A carrier has one copy of a recessive allele paired with a dominant allele on her other X chromosome, so she typically does not show the trait but can pass the allele to offspring.` },
      { q:`In a pedigree chart, a filled-in (shaded) symbol typically represents:`, ch:[`An individual affected by the trait being studied`,`An individual who is deceased`,`An individual of unknown sex`,`A pair of identical twins`], ans:0, exp:`In standard pedigree notation, a filled-in or shaded square or circle indicates that the individual displays the phenotype (trait) being tracked.` },
      { q:`In standard pedigree notation, squares and circles typically represent:`, ch:[`Affected and unaffected individuals, respectively`,`Carriers and non-carriers, respectively`,`Males and females, respectively`,`Dominant and recessive individuals, respectively`], ans:2, exp:`By convention in pedigree charts, squares represent males and circles represent females, with shading used separately to indicate whether the trait is expressed.` },
      { q:`If a father is affected by an X-linked recessive trait and the mother is homozygous unaffected (not a carrier), what is expected for their daughters?`, ch:[`All daughters will be affected`,`All daughters will be unaffected carriers, since each inherits the father's affected X and the mother's normal X`,`Half of daughters will be affected`,`None of the daughters will inherit an X chromosome from the father`], ans:1, exp:`Daughters receive one X from each parent, so they get the father's X carrying the recessive allele and the mother's normal X, making them heterozygous carriers rather than affected.` },
      { q:`Hemophilia, a well-known example of an X-linked recessive condition, primarily affects the body's ability to:`, ch:[`Produce insulin`,`Properly clot blood`,`Digest lactose`,`Regulate blood pressure`], ans:1, exp:`Hemophilia is an X-linked recessive condition in which the blood does not clot normally, due to a deficiency in certain clotting factor proteins.` },
      { q:`A pedigree analysis showing a trait that skips generations and appears more often in males is most consistent with which inheritance pattern?`, ch:[`X-linked recessive`,`Autosomal dominant`,`Y-linked (father to son only)`,`Simple autosomal recessive with equal sex distribution`], ans:0, exp:`X-linked recessive traits often appear more frequently in males and can skip generations, since unaffected female carriers can pass the allele on without showing the trait themselves.` },
      { q:`Because fathers pass their Y chromosome only to sons, Y-linked traits are:`, ch:[`Passed equally to sons and daughters`,`Never inherited by any offspring`,`Passed only from father to son`,`Always recessive`], ans:2, exp:`Since only males have a Y chromosome and fathers pass their Y chromosome only to their sons, Y-linked traits are inherited exclusively along the paternal line to sons.` },
      { q:`If a mother is a carrier for an X-linked recessive condition and the father is unaffected, what proportion of their sons is expected to be affected, on average?`, ch:[`0%`,`100%`,`25%`,`50%`], ans:3, exp:`Sons receive their only X chromosome from their mother, so if the mother is a carrier (one normal, one recessive X), on average half of her sons are expected to inherit the recessive X and be affected.` },
    ]
  },
  {
    id:`bb118`, cat:`Life Sciences`, title:`Taxonomy & the Tree of Life`, diff:`Easy`,
    qs:[
      { q:`Taxonomy is the branch of biology concerned with:`, ch:[`Studying enzyme reactions`,`Classifying and naming organisms based on shared characteristics`,`Studying weather patterns`,`Mapping the human genome only`], ans:1, exp:`Taxonomy is the scientific practice of classifying and naming living organisms based on shared characteristics and evolutionary relationships.` },
      { q:`The system of naming organisms with a two-part Latin name (genus + species) is called:`, ch:[`Cladistics`,`Dichotomous keying`,`Phylogenetics`,`Binomial nomenclature`], ans:3, exp:`Binomial nomenclature is the standardized system of giving each species a two-part Latin name, consisting of its genus and species, such as Homo sapiens.` },
      { q:`In the standard taxonomic hierarchy, which level is broader (contains more organisms)?`, ch:[`Species`,`Genus`,`Kingdom`,`Family`], ans:2, exp:`Kingdom is one of the broadest taxonomic ranks, containing many phyla, classes, orders, families, genera, and species within it.` },
      { q:`From broadest to most specific, which is the correct order of major taxonomic ranks?`, ch:[`Kingdom, Phylum, Class, Order, Family, Genus, Species`,`Species, Genus, Family, Order, Class, Phylum, Kingdom`,`Phylum, Kingdom, Class, Species, Order, Family, Genus`,`Genus, Species, Kingdom, Phylum, Class, Order, Family`], ans:0, exp:`The standard taxonomic hierarchy, from broadest to most specific, is Kingdom, Phylum, Class, Order, Family, Genus, Species.` },
      { q:`A phylogenetic tree (or tree of life) is used to represent:`, ch:[`The exact genome sequence of one organism`,`The evolutionary relationships and shared ancestry among different organisms`,`The digestive pathway of an animal`,`The chemical structure of DNA`], ans:1, exp:`A phylogenetic tree is a branching diagram that shows the estimated evolutionary relationships and shared common ancestry among different groups of organisms.` },
      { q:`The domain Eukarya includes which of the following groups?`, ch:[`Only bacteria`,`Only archaea`,`Only viruses`,`Animals, plants, fungi, and protists`], ans:3, exp:`The domain Eukarya includes all organisms whose cells contain a true nucleus, encompassing animals, plants, fungi, and protists.` },
      { q:`Which taxonomic domain is composed of prokaryotic organisms often found in extreme environments, and is distinct from bacteria?`, ch:[`Eukarya`,`Protista`,`Archaea`,`Fungi`], ans:2, exp:`Archaea are prokaryotic organisms that are genetically and biochemically distinct from bacteria, and many species are known for thriving in extreme environments.` },
      { q:`Two organisms placed in the same genus are generally expected to be:`, ch:[`More closely related than organisms in the same kingdom but different genera`,`Completely unrelated`,`Members of different domains`,`Incapable of being classified further`], ans:0, exp:`Organisms sharing the same genus are more closely related to one another than to organisms that only share a broader category, like kingdom or phylum.` },
      { q:`A species is often (though not perfectly) defined as a group of organisms that can:`, ch:[`Only survive in a single climate`,`Interbreed and produce fertile offspring`,`Photosynthesize`,`Live exclusively in water`], ans:1, exp:`A commonly used working definition of species is a group of organisms capable of interbreeding with one another to produce fertile offspring in nature.` },
      { q:`Which of these is one of the traditionally recognized kingdoms of life?`, ch:[`Domain`,`Species`,`Order`,`Animalia`], ans:3, exp:`Animalia is one of the traditionally recognized kingdoms of life, alongside others such as Plantae, Fungi, Protista, and various groupings of bacteria and archaea.` },
      { q:`Modern taxonomy increasingly relies on which type of evidence, in addition to physical traits, to classify organisms and determine relationships?`, ch:[`Astronomical data`,`Weather records`,`DNA and molecular sequence comparisons`,`Historical population counts`], ans:2, exp:`In addition to physical (morphological) traits, modern taxonomy increasingly uses DNA and molecular sequence comparisons to more accurately determine evolutionary relationships between organisms.` },
    ]
  },
];
